  const dataRows = clients.map(c => {
    const isExpired = c.membership?.status === 'expired' || c.membership?.daysRemaining < 0;
    const isExpiring = c.membership?.daysRemaining <= 5 && !isExpired;
    const statusLabel = isExpired ? 'VENCIDA / MOROSA' : isExpiring ? 'POR VENCER' : 'ACTIVA VIGENTE';

    return [
