      c.totalSpentInStore || 0,
      c.emergencyContact?.name || '',
      c.emergencyContact?.phone || '',
      c.medicalNotes || 'Sin notas'
    ];
  });

  const ws = XLSX.utils.aoa_to_sheet([...titleRows, headers, ...dataRows]);

