import React, { useState, useMemo } from 'react';
import { useGym } from '../../context/GymContext';
import { Client, MembershipPlanType } from '../../types';
import { getGymAvatar, getOfflineGymSvgAvatar, detectGender } from '../../utils/genderAvatar';
import { exportClientsToExcel } from '../../utils/excelExport';
import { sounds } from '../../services/audio';

// Modals
import { ClientFormModal } from './ClientFormModal';
import { ClientEditModal } from './ClientEditModal';
import { ClientDetailModal } from './ClientDetailModal';
import { BiometricEnrollModal } from './BiometricEnrollModal';
import { RenewMembershipModal } from './RenewMembershipModal';
import { ClientCredentialModal } from './ClientCredentialModal';

import { 
  Users, 
  UserPlus, 
  Search, 
  Fingerprint, 
  RefreshCw, 
  Eye, 
  Trash2, 
  Phone, 
  Mail, 
  Pencil, 
  LayoutGrid, 
  List, 
  ChevronRight,
  Download,
  CheckCircle2,
  AlertTriangle,
  Clock,
  Award,
  Crown,
  Share2,
  QrCode,
  DoorOpen,
  ArrowUpDown,
  Filter,
  X,
  Sparkles,
  Zap,
  Activity,
  Calendar,
  MessageCircle,
  ShieldCheck,
  Flame,
  Check,
  AlertCircle
} from 'lucide-react';

export const ClientList: React.FC = () => {
  const { 
    members, 
    deleteMember, 
    currentRole, 
    verifyBiometricAccess,
    todayCheckInsCount,
    activeBranch 
  } = useGym();

  // Filters & Search
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'expiring_soon' | 'expired' | 'no_fingerprint'>('all');
  const [tierFilter, setTierFilter] = useState<string>('all');
  const [sortBy, setSortBy] = useState<'urgency' | 'checkins' | 'name' | 'recent'>('urgency');
  const [viewMode, setViewMode] = useState<'table' | 'grid' | 'desk'>('table');

  // Modals state
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedClientForDetail, setSelectedClientForDetail] = useState<Client | null>(null);
  const [selectedClientForEdit, setSelectedClientForEdit] = useState<Client | null>(null);
  const [selectedClientForEnroll, setSelectedClientForEnroll] = useState<Client | null>(null);
  const [selectedClientForRenew, setSelectedClientForRenew] = useState<Client | null>(null);
  const [selectedClientForCredential, setSelectedClientForCredential] = useState<Client | null>(null);

  // Live Toast for Quick Turnstile / Access Test
  const [accessToast, setAccessToast] = useState<{
    visible: boolean;
    granted: boolean;
    clientName: string;
    message: string;
  } | null>(null);

  // Quick Turnstile Access Simulator
  const handleQuickAccessCheck = (e: React.MouseEvent, client: Client) => {
    e.stopPropagation();
    const result = verifyBiometricAccess(client.id);

    if (result.granted) {
      setAccessToast({
        visible: true,
        granted: true,
        clientName: client.fullName,
        message: `¡Pase Autorizado! Torniquete 1 Abierto • ${client.membership.planName}`,
      });
    } else {
      setAccessToast({
        visible: true,
        granted: false,
        clientName: client.fullName,
        message: result.reason || 'Acceso denegado: membresía inactiva o vencida',
      });
    }

    setTimeout(() => {
      setAccessToast(null);
    }, 4000);
  };

  // One-click WhatsApp message builder
  const handleSendWhatsApp = (e: React.MouseEvent, client: Client) => {
    e.stopPropagation();
    if (!client.phone) return;

    const isExpired = client.membership.status === 'expired' || client.membership.daysRemaining < 0;
    const isExpiring = client.membership.daysRemaining <= 5 && !isExpired;

    let message = '';
    if (isExpired) {
      const daysOverdue = Math.abs(client.membership.daysRemaining);
      message = `Hola ${client.fullName}! Te saludamos de Legends Pro Gym. Te recordamos que tu membresia (${client.membership.planName}) vencio hace ${daysOverdue} dias. Te extrañamos entrenando! Pasa a recepcion a renovarla y mantener tu condicion al maximo.`;
    } else if (isExpiring) {
      message = `Hola ${client.fullName}! Te saludamos de Legends Pro Gym. Te recordamos cordialmente que tu membresia (${client.membership.planName}) vence en ${client.membership.daysRemaining} dias (${client.membership.endDate}). Puedes renovar en caja con efectivo, tarjeta o transferencia para evitar interrupciones en tu acceso.`;
    } else {
      message = `Hola ${client.fullName}! Te saludamos de Legends Pro Gym. Tu membresia (${client.membership.planName}) se encuentra activa y vigente. Tienes alguna duda o solicitud especial en tu entrenamiento? Estamos a tu orden!`;
    }

    const cleanPhone = client.phone.replace(/\D/g, '');
    window.open(`https://wa.me/${cleanPhone}?text=${encodeURIComponent(message)}`, '_blank');
  };

  // Filter & Sort Logic
  const filteredMembers = useMemo(() => {
    return members
      .filter((member) => {
        // Search query
        const q = search.toLowerCase().trim();
        const matchesSearch = 
          !q ||
          member.fullName.toLowerCase().includes(q) ||
          member.documentId.toLowerCase().includes(q) ||
          member.phone.toLowerCase().includes(q) ||
          member.id.toLowerCase().includes(q) ||
          member.email.toLowerCase().includes(q) ||
          member.membership.planName.toLowerCase().includes(q);

        if (!matchesSearch) return false;

        // Status Filter
        const isExpired = member.membership.status === 'expired' || member.membership.daysRemaining < 0;
        const isExpiring = member.membership.daysRemaining <= 5 && !isExpired;
        const isActive = member.membership.daysRemaining > 5 && !isExpired;

        if (statusFilter === 'active' && !isActive) return false;
        if (statusFilter === 'expiring_soon' && !isExpiring) return false;
        if (statusFilter === 'expired' && !isExpired) return false;
        if (statusFilter === 'no_fingerprint' && member.biometricRegistered) return false;

        // Plan Tier Filter
        if (tierFilter !== 'all') {
          const planNameLower = member.membership.planName.toLowerCase();
          const planType = member.membership.planType;
          if (tierFilter === 'vip' && planType !== 'vip' && !planNameLower.includes('vip') && !planNameLower.includes('black')) return false;
          if (tierFilter === 'monthly' && planType !== 'monthly' && !planNameLower.includes('mensual')) return false;
          if (tierFilter === 'quarterly' && planType !== 'quarterly' && !planNameLower.includes('trimestral')) return false;
          if (tierFilter === 'daily' && planType !== 'daily' && !planNameLower.includes('día') && !planNameLower.includes('dia') && !planNameLower.includes('pass')) return false;
        }

        return true;
      })
      .sort((a, b) => {
        if (sortBy === 'urgency') {
          // Sort by days remaining ascending (expired/expiring first)
          return a.membership.daysRemaining - b.membership.daysRemaining;
        }
        if (sortBy === 'checkins') {
          return (b.checkInsCount || 0) - (a.checkInsCount || 0);
        }
        if (sortBy === 'name') {
          return a.fullName.localeCompare(b.fullName);
        }
        if (sortBy === 'recent') {
          return (b.createdAt || '').localeCompare(a.createdAt || '');
        }
        return 0;
      });
  }, [members, search, statusFilter, tierFilter, sortBy]);

  // Counts for KPI Summary
  const totalCount = members.length;
  const activeCount = members.filter(m => m.membership.daysRemaining > 5 && m.membership.status !== 'expired').length;
  const expiringCount = members.filter(m => m.membership.daysRemaining <= 5 && m.membership.daysRemaining >= 0 && m.membership.status !== 'expired').length;
  const expiredCount = members.filter(m => m.membership.status === 'expired' || m.membership.daysRemaining < 0).length;
  const noFingerprintCount = members.filter(m => !m.biometricRegistered).length;

  return (
    <div className="space-y-5">

      {/* Dynamic Access Test Toast */}
      {accessToast && (
        <div className={`fixed top-4 right-4 z-50 p-4 rounded-2xl border shadow-2xl backdrop-blur-md max-w-md animate-fade-in flex items-start gap-3 ${
          accessToast.granted 
            ? 'bg-[#0b1d14]/95 border-emerald-500/60 shadow-emerald-500/20 text-white' 
            : 'bg-[#21090a]/95 border-red-500/60 shadow-red-500/20 text-white'
        }`}>
          <div className={`p-2 rounded-xl shrink-0 ${
            accessToast.granted ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'
          }`}>
            {accessToast.granted ? <CheckCircle2 className="w-5 h-5" /> : <AlertCircle className="w-5 h-5" />}
          </div>
          <div className="flex-1 min-w-0">
            <h4 className="font-extrabold text-sm flex items-center justify-between">
              <span>{accessToast.clientName}</span>
              <span className="text-[10px] font-mono px-2 py-0.5 rounded uppercase tracking-wider bg-black/40">
                {accessToast.granted ? 'CONCEDIDO' : 'DENEGADO'}
              </span>
            </h4>
            <p className="text-xs text-zinc-300 mt-0.5 leading-snug">{accessToast.message}</p>
          </div>
          <button 
            onClick={() => setAccessToast(null)} 
            className="text-zinc-400 hover:text-white p-1"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* Main Top Header Banner */}
      <div className="relative bg-gradient-to-r from-[#14151c] via-[#101117] to-[#161722] p-5 sm:p-6 rounded-3xl border border-gym-border shadow-xl overflow-hidden">
        {/* Ambient subtle glow background */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-amber-500/10 rounded-full blur-3xl pointer-events-none -mr-20 -mt-20" />
        <div className="absolute bottom-0 left-1/3 w-64 h-64 bg-emerald-500/5 rounded-full blur-2xl pointer-events-none" />

        <div className="relative z-10 flex flex-col lg:flex-row items-start lg:items-center justify-between gap-5">
          <div>
            <div className="flex items-center gap-2.5">
              <div className="w-10 h-10 rounded-2xl bg-gradient-to-br from-amber-400 to-amber-600 flex items-center justify-center text-black font-black shadow-glow-gold">
                <Users className="w-5 h-5" />
              </div>
              <div>
                <div className="flex items-center gap-2 flex-wrap">
                  <h1 className="text-xl sm:text-2xl font-black text-white tracking-wide uppercase">
                    Cartera de Clientes & Membresías
                  </h1>
                  <span className="px-2.5 py-0.5 rounded-full bg-amber-500/15 border border-amber-500/30 text-amber-400 text-[10px] font-black tracking-widest uppercase">
                    CLUB PRO
                  </span>
                </div>
                <p className="text-xs sm:text-sm text-gym-muted mt-0.5">
                  Expedientes completos, vigencias en tiempo real, credenciales QR y enrolamiento biométrico.
                </p>
              </div>
            </div>

            {/* Hardware & Live Status Pills */}
            <div className="flex items-center gap-2.5 mt-3 flex-wrap text-xs">
              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 font-bold">
                <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
                <span>Torniquetes Biométricos Online (ZKTeco & RFID)</span>
              </span>

              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-xl bg-zinc-800/80 border border-zinc-700 text-zinc-300 font-semibold font-mono">
                <Activity className="w-3.5 h-3.5 text-amber-400" />
                <span>{todayCheckInsCount} Asistencias Hoy</span>
              </span>

              {activeBranch && (
                <span className="hidden sm:inline-flex items-center gap-1 px-2.5 py-1 rounded-xl bg-black/40 border border-white/10 text-zinc-400 text-[11px]">
                  <span>Sede:</span>
                  <strong className="text-zinc-200">{activeBranch.name}</strong>
                </span>
              )}
            </div>
          </div>

          {/* Action buttons */}
          <div className="flex items-center gap-2.5 w-full sm:w-auto justify-end flex-wrap">
            {/* Export Excel Button */}
            <button
              onClick={() => exportClientsToExcel(filteredMembers)}
              className="flex items-center gap-2 px-3.5 py-2.5 rounded-2xl bg-gym-surface hover:bg-zinc-800 text-zinc-200 hover:text-white border border-gym-border text-xs font-bold transition-all shadow-sm"
              title="Descargar padrón de clientes a Excel (.xlsx)"
            >
              <Download className="w-4 h-4 text-emerald-400" />
              <span>Exportar Excel</span>
            </button>

            {/* Add Client Button (Only admin & receptionist) */}
            {currentRole !== 'trainer' && (
              <button
                onClick={() => setShowAddModal(true)}
                className="flex items-center gap-2 px-5 py-2.5 rounded-2xl bg-gradient-to-r from-amber-500 to-amber-400 hover:from-amber-400 hover:to-amber-300 text-black font-extrabold text-sm shadow-glow-gold hover:shadow-[0_0_30px_rgba(245,158,11,0.6)] transition-all transform hover:-translate-y-0.5 active:translate-y-0"
              >
                <UserPlus className="w-4 h-4 stroke-[3]" />
                <span>Nuevo Cliente</span>
              </button>
            )}
          </div>
        </div>
      </div>

      {/* KPI Cards Grid with Rich Textures and Glow Effects */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3 sm:gap-4">

        {/* Total Cartera */}
        <div 
          onClick={() => setStatusFilter('all')}
          className={`relative p-4 rounded-2xl border cursor-pointer transition-all duration-300 overflow-hidden ${
            statusFilter === 'all' 
              ? 'bg-gradient-to-br from-amber-500/20 via-[#181922] to-[#12131a] border-amber-500 ring-2 ring-amber-500/30 shadow-glow-gold/20' 
              : 'bg-gym-card/90 hover:bg-[#161720] border-gym-border hover:border-zinc-600'
          }`}
        >
          <div className="flex items-center justify-between text-xs text-gym-muted mb-1 font-semibold">
            <span>Total Cartera</span>
            <Users className="w-4 h-4 text-amber-400 opacity-80" />
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-3xl font-black text-white">{totalCount}</span>
            <span className="text-[11px] font-bold text-zinc-400 font-mono">socios</span>
          </div>
          <p className="text-[11px] text-zinc-400 mt-1 truncate">
            {activeCount} vigentes ({totalCount ? Math.round((activeCount / totalCount) * 100) : 0}%)
          </p>
        </div>

        {/* Activos Vigentes */}
        <div 
          onClick={() => setStatusFilter('active')}
          className={`relative p-4 rounded-2xl border cursor-pointer transition-all duration-300 overflow-hidden ${
            statusFilter === 'active' 
              ? 'bg-gradient-to-br from-emerald-500/20 via-[#131c17] to-[#0e1411] border-emerald-500 ring-2 ring-emerald-500/30 shadow-glow-green/20' 
              : 'bg-gym-card/90 hover:bg-[#131a15] border-gym-border hover:border-emerald-500/40'
          }`}
        >
          <div className="flex items-center justify-between text-xs text-emerald-400 mb-1 font-bold">
            <span>Activos Vigentes</span>
            <CheckCircle2 className="w-4 h-4 text-emerald-400" />
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-3xl font-black text-emerald-400">{activeCount}</span>
            <span className="text-[10px] font-extrabold uppercase px-1.5 py-0.5 rounded bg-emerald-500/20 text-emerald-300">
              Pase OK
            </span>
          </div>
          <p className="text-[11px] text-emerald-400/80 mt-1 truncate">
            Acceso libre al torniquete
          </p>
        </div>

        {/* Por Vencer (<= 5 días) */}
        <div 
          onClick={() => setStatusFilter('expiring_soon')}
          className={`relative p-4 rounded-2xl border cursor-pointer transition-all duration-300 overflow-hidden ${
            statusFilter === 'expiring_soon' 
              ? 'bg-gradient-to-br from-amber-500/25 via-[#221c11] to-[#17130a] border-amber-500 ring-2 ring-amber-500/40 shadow-glow-gold/25' 
              : 'bg-gym-card/90 hover:bg-[#1f1a10] border-gym-border hover:border-amber-500/40'
          }`}
        >
          <div className="flex items-center justify-between text-xs text-amber-400 mb-1 font-bold">
            <span className="flex items-center gap-1">
              <span>Por Vencer (&le; 5 d)</span>
              {expiringCount > 0 && <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span>}
            </span>
            <Clock className="w-4 h-4 text-amber-400" />
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-3xl font-black text-amber-400">{expiringCount}</span>
            <span className="text-[10px] font-extrabold uppercase px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-300">
              Urgente
            </span>
          </div>
          <p className="text-[11px] text-amber-400/80 mt-1 truncate">
            Requieren aviso de renovación
          </p>
        </div>

        {/* Vencidos / Morosos */}
        <div 
          onClick={() => setStatusFilter('expired')}
          className={`relative p-4 rounded-2xl border cursor-pointer transition-all duration-300 overflow-hidden ${
            statusFilter === 'expired' 
              ? 'bg-gradient-to-br from-red-500/20 via-[#221113] to-[#170a0c] border-red-500 ring-2 ring-red-500/30 shadow-glow-red/20' 
              : 'bg-gym-card/90 hover:bg-[#1c0f11] border-gym-border hover:border-red-500/40'
          }`}
        >
          <div className="flex items-center justify-between text-xs text-red-400 mb-1 font-bold">
            <span>Vencidos / Morosos</span>
            <AlertTriangle className="w-4 h-4 text-red-400" />
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-3xl font-black text-red-400">{expiredCount}</span>
            <span className="text-[10px] font-extrabold uppercase px-1.5 py-0.5 rounded bg-red-500/20 text-red-300">
              Bloqueado
            </span>
          </div>
          <p className="text-[11px] text-red-400/80 mt-1 truncate">
            Acceso denegado en molinete
          </p>
        </div>

        {/* Sin Huella Enrolada */}
        <div 
          onClick={() => setStatusFilter('no_fingerprint')}
          className={`relative p-4 rounded-2xl border cursor-pointer transition-all duration-300 overflow-hidden col-span-2 sm:col-span-1 ${
            statusFilter === 'no_fingerprint' 
              ? 'bg-gradient-to-br from-purple-500/20 via-[#1b1426] to-[#120c1b] border-purple-500 ring-2 ring-purple-500/30' 
              : 'bg-gym-card/90 hover:bg-[#181122] border-gym-border hover:border-purple-500/40'
          }`}
        >
          <div className="flex items-center justify-between text-xs text-purple-400 mb-1 font-bold">
            <span>Sin Huella Enrolada</span>
            <Fingerprint className="w-4 h-4 text-purple-400" />
          </div>
          <div className="flex items-baseline gap-2">
            <span className="text-3xl font-black text-purple-400">{noFingerprintCount}</span>
            <span className="text-[10px] font-extrabold uppercase px-1.5 py-0.5 rounded bg-purple-500/20 text-purple-300">
              Biometría
            </span>
          </div>
          <p className="text-[11px] text-purple-400/80 mt-1 truncate">
            Pendiente captura dactilar
          </p>
        </div>

      </div>

      {/* Search, Filter Tabs and View Controls Bar */}
      <div className="bg-[#12131a] p-4 rounded-2xl border border-gym-border flex flex-col lg:flex-row items-stretch lg:items-center justify-between gap-3 shadow-md">

        {/* Search Input */}
        <div className="relative flex-1 max-w-md">
          <Search className="w-4 h-4 text-gym-muted absolute left-3.5 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por nombre, DNI, teléfono o ID..."
