                    className="text-xs font-bold text-amber-400 hover:text-amber-300 flex items-center gap-1 py-1"
                  >
                    <span>Expediente</span>
                    <ChevronRight className="w-3.5 h-3.5" />
                  </button>

                  <div className="flex items-center gap-1">
                    <button
                      onClick={(e) => handleQuickAccessCheck(e, member)}
                      className="p-1.5 rounded-lg bg-gym-surface hover:bg-amber-500/20 text-zinc-300 hover:text-amber-400 border border-gym-border transition-colors"
                      title="Simular Pase de Torniquete"
                    >
                      <DoorOpen className="w-3.5 h-3.5" />
                    </button>

                    <button
                      onClick={() => setSelectedClientForCredential(member)}
                      className="p-1.5 rounded-lg bg-gym-surface hover:bg-white/10 text-zinc-300 hover:text-white border border-gym-border transition-colors"
                      title="Credencial Digital"
                    >
                      <QrCode className="w-3.5 h-3.5 text-amber-400" />
                    </button>

                    {currentRole !== 'trainer' && (
                      <button
                        onClick={() => setSelectedClientForRenew(member)}
                        className="p-1.5 rounded-lg bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-400 border border-emerald-500/30 transition-colors"
                        title="Renovar membresía"
                      >
                        <RefreshCw className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </div>
                </div>

              </div>
            );
          })}
        </div>

      ) : (

        /* ============================================================== */
        /* VIEW 3: MESA DE RENOVACIONES (RECEPCIONIST FOLLOW-UP DESK)       */
        /* ============================================================== */
        <div className="space-y-4">
          <div className="p-4 rounded-2xl bg-amber-500/10 border border-amber-500/30 flex items-center gap-3">
            <Zap className="w-5 h-5 text-amber-400 shrink-0" />
            <div className="text-xs text-zinc-300 leading-relaxed">
              <strong className="text-white">Mesa de Renovaciones y Cobranza Rápida:</strong> Esta vista prioriza los socios que vencieron recientemente o vencen en los próximos 5 días. Utiliza el botón de WhatsApp para enviar el recordatorio precargado con un solo clic.
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredMembers
              .filter(m => m.membership.daysRemaining <= 5 || m.membership.status === 'expired')
              .map((member) => {
                const isExpired = member.membership.status === 'expired' || member.membership.daysRemaining < 0;

                return (
                  <div 
                    key={member.id}
                    className={`p-5 rounded-3xl border shadow-xl flex flex-col justify-between ${
                      isExpired 
                        ? 'bg-gradient-to-br from-[#230f12] via-[#141015] to-[#0c0d12] border-red-500/40' 
                        : 'bg-gradient-to-br from-[#241a0d] via-[#151318] to-[#0c0d12] border-amber-500/40'
                    }`}
                  >
                    <div>
                      <div className="flex items-center justify-between mb-3">
                        <span className={`text-[10px] font-black uppercase px-2.5 py-0.5 rounded-full ${
                          isExpired ? 'bg-red-500 text-white' : 'bg-amber-400 text-black'
                        }`}>
                          {isExpired ? 'Acceso Bloqueado' : 'Próximo a Vencer'}
                        </span>

                        <span className={`text-xs font-black font-mono ${isExpired ? 'text-red-400' : 'text-amber-400'}`}>
                          {member.membership.daysRemaining >= 0 
                            ? `Vence en ${member.membership.daysRemaining} días` 
                            : `Venció hace ${Math.abs(member.membership.daysRemaining)} días`}
                        </span>
                      </div>

                      <div className="flex items-center gap-3 mb-3">
                        <img
                          src={getGymAvatar(member.fullName, member.avatarUrl)}
                          alt={member.fullName}
                          className="w-12 h-12 rounded-2xl object-cover border border-white/20"
                        />
                        <div>
                          <h4 className="font-black text-white text-base leading-tight">{member.fullName}</h4>
                          <p className="text-xs text-zinc-400 font-mono">DNI: {member.documentId} • ID: {member.id}</p>
                        </div>
                      </div>

                      <div className="p-3 bg-black/40 rounded-2xl border border-white/10 space-y-1 text-xs mb-4">
                        <div className="flex justify-between">
                          <span className="text-gym-muted">Plan Actual:</span>
                          <span className="font-bold text-white">{member.membership.planName}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gym-muted">Costo Renovación:</span>
                          <span className="font-black text-amber-400 font-mono">${member.membership.price.toLocaleString()} MXN</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gym-muted">Fecha Límite:</span>
                          <span className="font-mono text-zinc-300">{member.membership.endDate}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-2 pt-2 border-t border-white/10">
                      <button
                        onClick={(e) => handleSendWhatsApp(e, member)}
                        className="flex-1 py-2.5 rounded-xl bg-emerald-500 hover:bg-emerald-400 text-black font-black text-xs flex items-center justify-center gap-1.5 transition-all shadow-md"
                      >
                        <Phone className="w-3.5 h-3.5" />
                        <span>Aviso WhatsApp</span>
                      </button>

                      <button
                        onClick={() => setSelectedClientForRenew(member)}
                        className="px-4 py-2.5 rounded-xl bg-amber-500 hover:bg-amber-400 text-black font-black text-xs flex items-center justify-center gap-1.5 transition-all shadow-glow-gold"
                      >
                        <RefreshCw className="w-3.5 h-3.5" />
                        <span>Renovar</span>
                      </button>
                    </div>

                  </div>
                );
              })}
          </div>
        </div>

      )}

      {/* ============================================================== */}
      {/* ALL MODAL DIALOGS                                              */}
      {/* ============================================================== */}

      {/* 1. Add Client Modal */}
      {showAddModal && (
        <ClientFormModal
          onClose={() => setShowAddModal(false)}
          onClientCreated={(newClient, wantsEnrollment) => {
            setShowAddModal(false);
            if (wantsEnrollment) {
              setSelectedClientForEnroll(newClient);
            }
          }}
        />
      )}

      {/* 2. Edit Client Modal */}
      {selectedClientForEdit && (
        <ClientEditModal
          client={selectedClientForEdit}
          onClose={() => setSelectedClientForEdit(null)}
          onClientUpdated={(updatedClient) => {
            setSelectedClientForEdit(null);
          }}
        />
      )}

      {/* 3. Detail Dossier Modal */}
      {selectedClientForDetail && (
        <ClientDetailModal
          client={selectedClientForDetail}
          onClose={() => setSelectedClientForDetail(null)}
          onEdit={() => {
            const client = selectedClientForDetail;
            setSelectedClientForDetail(null);
            setSelectedClientForEdit(client);
          }}
          onEnrollBiometric={() => {
            const client = selectedClientForDetail;
            setSelectedClientForDetail(null);
            setSelectedClientForEnroll(client);
          }}
          onRenewMembership={() => {
            const client = selectedClientForDetail;
            setSelectedClientForDetail(null);
            setSelectedClientForRenew(client);
          }}
        />
      )}

      {/* 4. Biometric Fingerprint Capture Wizard */}
      {selectedClientForEnroll && (
        <BiometricEnrollModal
          client={selectedClientForEnroll}
          onClose={() => setSelectedClientForEnroll(null)}
          onSuccess={() => setSelectedClientForEnroll(null)}
        />
      )}

      {/* 5. Renew Membership Modal */}
      {selectedClientForRenew && (
        <RenewMembershipModal
          client={selectedClientForRenew}
          onClose={() => setSelectedClientForRenew(null)}
        />
      )}

      {/* 6. Digital Credential Pass with QR & Barcode */}
      {selectedClientForCredential && (
        <ClientCredentialModal
          client={selectedClientForCredential}
          onClose={() => setSelectedClientForCredential(null)}
        />
      )}

    </div>
  );
};

