            return (
              <div
                key={member.id}
                onClick={() => setSelectedClientForDetail(member)}
                className={`group relative rounded-3xl border p-4 transition-all duration-300 cursor-pointer shadow-lg hover:shadow-2xl flex flex-col justify-between ${
                  isVip 
                    ? 'bg-gradient-to-b from-[#19150b] via-[#12131b] to-[#0c0d12] border-amber-500/40 hover:border-amber-400 shadow-amber-500/5' 
                    : 'bg-[#12131a] hover:bg-[#161722] border-gym-border hover:border-zinc-500'
                }`}
              >
                <div>
                  {/* Top Status & Biometric Badges */}
                  <div className="flex items-center justify-between gap-2 mb-3">
                    <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded-full border ${
                      isExpired 
                        ? 'bg-red-500/20 text-red-400 border-red-500/30' 
                        : isExpiring 
                        ? 'bg-amber-500/20 text-amber-400 border-amber-500/30' 
                        : 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30'
                    }`}>
                      {isExpired ? 'Vencida' : isExpiring ? 'Por Vencer' : 'Activa'}
                    </span>

                    {member.biometricRegistered ? (
                      <span className="flex items-center gap-1 text-[11px] text-emerald-400 font-bold bg-emerald-500/10 px-2 py-0.5 rounded-lg border border-emerald-500/20">
                        <Fingerprint className="w-3 h-3" />
                        <span>Huella OK</span>
                      </span>
                    ) : (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setSelectedClientForEnroll(member);
                        }}
                        className="flex items-center gap-1 text-[10px] text-purple-300 hover:text-purple-200 font-bold px-2 py-0.5 rounded-lg bg-purple-500/15 border border-purple-500/30 transition-colors"
                      >
                        <Fingerprint className="w-3 h-3 text-purple-400" />
                        <span>Capturar</span>
                      </button>
                    )}
                  </div>

                  {/* Avatar & Identification */}
                  <div className="flex items-center gap-3 mb-3">
                    <div className="relative shrink-0">
                      <img
                        src={getGymAvatar(member.fullName, member.avatarUrl)}
                        alt={member.fullName}
                        onError={(e) => {
                          (e.currentTarget as HTMLImageElement).src = getOfflineGymSvgAvatar(detectGender(member.fullName));
                        }}
                        className={`w-12 h-12 rounded-2xl object-cover border-2 shadow-md transition-transform group-hover:scale-105 ${
                          isExpired 
                            ? 'border-red-500' 
                            : isExpiring 
                            ? 'border-amber-400' 
                            : 'border-emerald-400'
                        }`}
                      />
                      {isVip && (
                        <span className="absolute -top-1.5 -right-1.5 w-4.5 h-4.5 rounded-full bg-gradient-to-br from-amber-400 to-amber-600 flex items-center justify-center text-black shadow-md">
                          <Crown className="w-2.5 h-2.5 fill-black text-black" />
                        </span>
                      )}
                    </div>

                    <div className="min-w-0 flex-1">
                      <h3 className="font-extrabold text-white text-sm group-hover:text-amber-400 transition-colors truncate">
                        {member.fullName}
                      </h3>
                      <div className="flex items-center gap-1.5 text-[11px] text-gym-muted font-mono mt-0.5">
                        <span className="text-zinc-300 font-bold">{member.id}</span>
                        <span>•</span>
                        <span>DNI: {member.documentId || 'S/N'}</span>
                      </div>
                    </div>
                  </div>

                  {/* Membership Info Box */}
                  <div className="bg-[#181924]/80 rounded-2xl p-2.5 border border-white/5 mb-2.5 space-y-1">
                    <div className="flex items-center justify-between text-xs">
                      <span className="font-bold text-white truncate max-w-[65%]">
                        {member.membership.planName}
                      </span>
                      <span className="text-amber-400 font-black font-mono text-xs">
                        ${member.membership.price.toLocaleString()}
                      </span>
                    </div>

                    <div className="flex items-center justify-between text-[11px] text-gym-muted">
                      <span>Vigencia:</span>
                      <span className={`font-bold font-mono ${
                        isExpired ? 'text-red-400' : isExpiring ? 'text-amber-400' : 'text-emerald-400'
                      }`}>
                        {member.membership.daysRemaining >= 0 
                          ? `${member.membership.daysRemaining} días`
                          : `Venció hace ${Math.abs(member.membership.daysRemaining)} d`}
                      </span>
                    </div>

                    <div className="w-full bg-zinc-800 rounded-full h-1 overflow-hidden">
                      <div 
                        className={`h-full rounded-full ${
                          isExpired ? 'bg-red-500 w-full' : isExpiring ? 'bg-amber-400 w-1/4' : 'bg-emerald-400 w-3/4'
                        }`} 
                      />
                    </div>
                  </div>

                  {/* Activity Snippet */}
                  <div className="flex items-center justify-between text-[11px] text-zinc-400 px-1 mb-2">
                    <span className="flex items-center gap-1 font-mono">
                      <Activity className="w-3 h-3 text-amber-400" />
                      <span>{member.checkInsCount || 0} visitas</span>
                    </span>
                    {member.phone && (
                      <span 
                        onClick={(e) => handleSendWhatsApp(e, member)}
                        className="text-emerald-400 hover:underline flex items-center gap-1 cursor-pointer"
                        title="Enviar WhatsApp"
                      >
                        <Phone className="w-3 h-3" />
                        <span>WhatsApp</span>
                      </span>
                    )}
                  </div>
                </div>

                {/* Card Footer: Expediente + Quick action buttons */}
                <div className="border-t border-white/10 pt-2.5 mt-2 flex items-center justify-between gap-1" onClick={(e) => e.stopPropagation()}>
                  <button
                    onClick={() => setSelectedClientForDetail(member)}
                    className="text-xs font-bold text-amber-400 hover:text-amber-300 flex items-center gap-1 py-1"
                  >
                    <span>Expediente</span>
                    <ChevronRight className="w-3.5 h-3.5" />
                  </button>

                  <div className="flex items-center gap-1">
                    <button
                      onClick={(e) => handleQuickAccessCheck(e, member)}
                      className="p-1.5 rounded-lg bg-gym-surface hover:bg-amber-500/20 text-zinc-300 hover:text-amber-400 border border-gym-border transition-colors"
                      title="Simular Pase de Torniquete"
                    >
                      <DoorOpen className="w-3.5 h-3.5" />
                    </button>

                    <button
                      onClick={() => setSelectedClientForCredential(member)}
                      className="p-1.5 rounded-lg bg-gym-surface hover:bg-white/10 text-zinc-300 hover:text-white border border-gym-border transition-colors"
                      title="Credencial Digital"
                    >
                      <QrCode className="w-3.5 h-3.5 text-amber-400" />
                    </button>

                    {currentRole !== 'trainer' && (
                      <button
                        onClick={() => setSelectedClientForRenew(member)}
                        className="p-1.5 rounded-lg bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-400 border border-emerald-500/30 transition-colors"
                        title="Renovar membresía"
                      >
                        <RefreshCw className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </div>
                </div>

              </div>
            );
          })}
        </div>

      ) : (

        /* ============================================================== */
        /* VIEW 3: MESA DE RENOVACIONES (RECEPCIONIST FOLLOW-UP DESK)       */
        /* ============================================================== */
        <div className="space-y-4">
          <div className="p-3.5 rounded-2xl bg-amber-500/10 border border-amber-500/30 flex items-center gap-3">
            <Zap className="w-5 h-5 text-amber-400 shrink-0" />
            <div className="text-xs text-zinc-300 leading-relaxed">
              <strong className="text-white">Mesa de Seguimiento & Cobranza Prioritaria:</strong> Aquí se concentran los socios con vigencia menor a 5 días o membresía vencida. Pulsa en <strong>Aviso WhatsApp</strong> para abrir la conversación con el recordatorio listo para enviar.
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredMembers
              .filter(m => m.membership.daysRemaining <= 5 || m.membership.status === 'expired')
              .map((member) => {
                const isExpired = member.membership.status === 'expired' || member.membership.daysRemaining < 0;

                return (
                  <div 
                    key={member.id}
                    className={`p-4 sm:p-5 rounded-3xl border shadow-xl flex flex-col justify-between ${
                      isExpired 
                        ? 'bg-gradient-to-br from-[#230f12] via-[#141015] to-[#0c0d12] border-red-500/40' 
                        : 'bg-gradient-to-br from-[#241a0d] via-[#151318] to-[#0c0d12] border-amber-500/40'
                    }`}
                  >
                    <div>
                      <div className="flex items-center justify-between mb-3">
                        <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded-full ${
                          isExpired ? 'bg-red-500 text-white' : 'bg-amber-400 text-black'
                        }`}>
                          {isExpired ? 'Acceso Bloqueado' : 'Próximo a Vencer'}
                        </span>

                        <span className={`text-xs font-black font-mono ${isExpired ? 'text-red-400' : 'text-amber-400'}`}>
                          {member.membership.daysRemaining >= 0 
                            ? `Vence en ${member.membership.daysRemaining} días` 
                            : `Venció hace ${Math.abs(member.membership.daysRemaining)} días`}
                        </span>
                      </div>

                      <div className="flex items-center gap-3 mb-3">
                        <img
                          src={getGymAvatar(member.fullName, member.avatarUrl)}
                          alt={member.fullName}
                          className="w-12 h-12 rounded-2xl object-cover border border-white/20"
                        />
                        <div className="min-w-0">
                          <h4 className="font-black text-white text-sm leading-tight truncate">{member.fullName}</h4>
                          <p className="text-xs text-zinc-400 font-mono">DNI: {member.documentId} • ID: {member.id}</p>
                        </div>
                      </div>

                      <div className="p-3 bg-black/40 rounded-2xl border border-white/10 space-y-1 text-xs mb-3">
                        <div className="flex justify-between">
                          <span className="text-gym-muted">Plan Actual:</span>
                          <span className="font-bold text-white truncate max-w-[60%]">{member.membership.planName}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gym-muted">Costo Renovación:</span>
                          <span className="font-black text-amber-400 font-mono">${member.membership.price.toLocaleString()} MXN</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gym-muted">Fecha Límite:</span>
                          <span className="font-mono text-zinc-300">{member.membership.endDate}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-2 pt-2 border-t border-white/10">
                      <button
                        onClick={(e) => handleSendWhatsApp(e, member)}
                        className="flex-1 py-2 rounded-xl bg-emerald-500 hover:bg-emerald-400 text-black font-black text-xs flex items-center justify-center gap-1.5 transition-all shadow-md"
                      >
                        <Phone className="w-3.5 h-3.5" />
                        <span>Aviso WhatsApp</span>
                      </button>

                      <button
                        onClick={() => setSelectedClientForRenew(member)}
                        className="px-3.5 py-2 rounded-xl bg-amber-500 hover:bg-amber-400 text-black font-black text-xs flex items-center justify-center gap-1.5 transition-all shadow-glow-gold"
                      >
                        <RefreshCw className="w-3.5 h-3.5" />
                        <span>Renovar</span>
                      </button>
                    </div>

                  </div>
                );
              })}
          </div>
        </div>

      )}

      {/* ============================================================== */}
      {/* ALL MODAL DIALOGS                                              */}
      {/* ============================================================== */}

      {/* 1. Add Client Modal */}
      {showAddModal && (
        <ClientFormModal
          onClose={() => setShowAddModal(false)}
          onClientCreated={(newClient, wantsEnrollment) => {
            setShowAddModal(false);
            if (wantsEnrollment) {
              setSelectedClientForEnroll(newClient);
            }
          }}
        />
      )}

      {/* 2. Edit Client Modal */}
      {selectedClientForEdit && (
        <ClientEditModal
          client={selectedClientForEdit}
          onClose={() => setSelectedClientForEdit(null)}
          onClientUpdated={(updatedClient) => {
            setSelectedClientForEdit(null);
          }}
        />
      )}

      {/* 3. Detail Dossier Modal */}
      {selectedClientForDetail && (
        <ClientDetailModal
          client={selectedClientForDetail}
          onClose={() => setSelectedClientForDetail(null)}
          onEdit={() => {
            const client = selectedClientForDetail;
            setSelectedClientForDetail(null);
            setSelectedClientForEdit(client);
          }}
          onEnrollBiometric={() => {
            const client = selectedClientForDetail;
            setSelectedClientForDetail(null);
            setSelectedClientForEnroll(client);
          }}
          onRenewMembership={() => {
            const client = selectedClientForDetail;
            setSelectedClientForDetail(null);
            setSelectedClientForRenew(client);
          }}
        />
      )}

      {/* 4. Biometric Fingerprint Capture Wizard */}
      {selectedClientForEnroll && (
        <BiometricEnrollModal
          client={selectedClientForEnroll}
          onClose={() => setSelectedClientForEnroll(null)}
          onSuccess={() => setSelectedClientForEnroll(null)}
        />
      )}

      {/* 5. Renew Membership Modal */}
      {selectedClientForRenew && (
        <RenewMembershipModal
          client={selectedClientForRenew}
          onClose={() => setSelectedClientForRenew(null)}
        />
      )}

      {/* 6. Digital Credential Pass with QR & Barcode */}
      {selectedClientForCredential && (
        <ClientCredentialModal
          client={selectedClientForCredential}
          onClose={() => setSelectedClientForCredential(null)}
        />
      )}

    </div>
  );
};

